function normalizeBooking(record, kind) {
  const patientName = kind === 'consultation' ? record.name : `${record.firstName || ''} ${record.lastName || ''}`.trim();
  return {
    ...record,
    kind,
    // 'appointment' | 'consultation'
    type: kind === 'consultation' ? 'online' : record.type,
    patientName,
    notes: record.notes || ''
  };
}

