              </div>
            </div>
          </div>
        )}

        {/* APPOINTMENTS */}
        {tab === 'appointments' && (
          <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
              <h2 style={S.sectionHLight}>My Appointments</h2>
              <button onClick={() => setTab('online')} style={S.btnGold}>+ Book New</button>
